functions.UnifiedBrief:
function UnifiedBrief({profile,view,customer,filters,ai}){
  const [result,setResult]=useState(profile.combined),[busy,setBusy]=useState(false);
  async function generate(){setBusy(true);try{setResult(await api('/customer-intelligence/brief',{view,customer_id:customer,...filters,ai}));}catch(e){setResult({...profile.combined,source:'Deterministic explanation · '+e.message});}finally{setBusy(false);}}
  return <section className="panel insights" aria-busy={busy}><div className="panel-heading"><div className="insight-title"><Sparkles size={23}/><h2>AI-assisted engagement brief</h2><span className="pill">{ai?'Cortex AI':'Rules & SQL'}</span></div><button className="button primary" disabled={busy} onClick={generate}>{busy?<LoaderCircle className="spin" size={16}/>:<Sparkles size={16}/>} {busy?'Preparing brief…':'Generate engagement brief'}</button></div>
    <div className="insight-grid"><div><div className="eyebrow muted">RETENTION ACTION</div><p className="finding">{result.finding}</p></div><div><div className="eyebrow muted">VERIFIED CUSTOMER EVIDENCE</div><ul>{result.ids.slice(0,3).map(i=><li key={i}>{result.facts[i]}</li>)}</ul></div><div><div className="eyebrow muted">SUGGESTED NEXT ACTION</div><p>{result.action}</p></div></div>
    <p className="insight-source" role="status">{busy?'Checking verified evidence with Cortex…':result.source} · Human review required. No customer message is sent.</p>
    <details><summary>Supporting evidence for this brief<ChevronDown size={16}/></summary><ul>{result.facts.map((fact,i)=><li key={i}>{fact}</li>)}</ul></details>
  </section>;
}

functions.CustomerIntelligence:
function CustomerIntelligence({revision,ai}){
  const [view,setView]=useState(customerTab),[filters,setFilters]=useState({risk:'All',value:'All',channel:'All'}),[selected,setSelected]=useState(null),[search,setSearch]=useState('');
  useEffect(()=>{const update=()=>{setView(customerTab());setSelected(null);setSearch('');};window.addEventListener('hashchange',update);return()=>window.removeEventListener('hashchange',update);},[]);
  const nbo=view==='CROSS_SELL',priorities=view==='PRIORITIES';
  const result=useData('/customer-intelligence?'+query({view,...filters}),revision),data=result.data;
  const rows=data?.rows||[],visible=rows.filter(r=>r.CUSTOMER_ID.toLowerCase().includes(search.toLowerCase())),row=visible.find(r=>r.CUSTOMER_ID===selected)||visible[0],counts=data?.counts,profile=row?data.profiles[row.CUSTOMER_ID]:null;
  const snapshot=data?.snapshot,renewalStart=snapshot?new Date(snapshot.slice(0,7)+'-01T00:00:00'):null;
  if(renewalStart)renewalStart.setMonth(renewalStart.getMonth()+1);
  const renewalEnd=renewalStart?new Date(renewalStart):null;if(renewalEnd){renewalEnd.setMonth(renewalEnd.getMonth()+3);renewalEnd.setDate(renewalEnd.getDate()-1);}
  const change=(key,value)=>{setFilters(f=>({...f,[key]:value}));setSelected(null);setSearch('');};
  const tabs=[['PRIORITIES','Customer Priorities','priorities'],['RETENTION','Retention Actions','retention'],['CROSS_SELL','Cross-Sell Opportunities','cross-sell']];
  function tab(value,slug){setView(value);setSelected(null);setSearch('');location.hash='CUSTOMERS/'+slug;}
  function tabKey(event,index){if(!['ArrowRight','ArrowLeft','Home','End'].includes(event.key))return;event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tab(tabs[next][0],tabs[next][2]);document.getElementById('tab-'+tabs[next][0])?.focus();}
  return <><PageHeader title="Customer Growth & Retention Intelligence" subtitle="One customer view. Retention-led priorities and evidence-based growth opportunities."/>
    <div className="customer-tabs" role="tablist" aria-label="Customer intelligence views">{tabs.map(([id,label,slug],index)=><button type="button" key={id} id={'tab-'+id} role="tab" tabIndex={view===id?0:-1} onKeyDown={event=>tabKey(event,index)} aria-selected={view===id} aria-controls="customer-workspace" className={view===id?'active':''} onClick={()=>tab(id,slug)}>{label}</button>)}</div>
    <div id="customer-workspace" role="tabpanel" aria-labelledby={'tab-'+view}>
    {result.error?<ErrorState message={result.error}/>:result.loading||data?.view!==view?<Loading/>:<>
      {nbo&&<div className="opportunity-headline"><span className="metric-icon"><Target size={23}/></span><div><h2>{number(counts.total)} Motor-to-Travel cross-sell candidates</h2><p>Existing validated segment. Eligibility, suitability and propensity are not established.</p></div></div>}
      <div className="kpi-grid">{(priorities?[['Unique customers',data.summary.portfolio_total,Users],['Priority retention opportunities',counts.priority,Shield],['Cross-sell candidates',data.summary.cross_sell_candidates,Target],['High-value at risk',counts.high_value_at_risk,Layers]]:nbo?[['Total candidates',counts.total,Users],['High / Top value',counts.high_value,Layers],['High-risk candidates',counts.high_risk,Shield],['Priority opportunities',counts.priority,Target]]:[['Customers in portfolio',counts.total,Users],['High-risk customers',counts.high_risk,Shield],['High-value at risk',counts.high_value_at_risk,Layers],['Priority retention opportunities',counts.priority,Target]]).map(([label,value,icon])=><KPI key={label} label={label} value={number(value)} icon={icon} detail={label.includes('Priority')?(nbo?'Low risk · High/Top value':'High risk · High/Top value · Renewal window'):priorities?'Full portfolio · Overlapping segments':'Full segment overview'}/>)}</div>
      <div className="scope-note"><CheckCircle2 size={14}/>Snapshot {snapshot} · Cards describe the full portfolio or segment; filters refine the worklist · Values in RM</div>
      {priorities&&<p className="customer-overlap-note">{data.summary.overlap_note} Customer Priorities shows each customer once, in the existing retention-priority order.</p>}
      <div className="customer-filters"><SlidersHorizontal size={17}/>{['risk','value','channel'].map(key=><Select key={key} label={key==='risk'?'Retention risk':key==='value'?'Customer value':'Preferred channel'} value={filters[key]} onChange={v=>change(key,v)} options={['All',...data.options[key]].map(value=>({value,label:(key==='risk'?'Risk':key==='value'?'Value':'Channel')+': '+value}))}/>)}</div>
      <div className="customer-grid"><Panel title={priorities?'Consolidated customer priorities':nbo?'Ranked cross-sell candidates':'Retention worklist'} subtitle={`${number(data.filtered_total)} unique customers match · First ${number(rows.length)} shown`} action={<label className="search"><Search size={15}/><input aria-label="Find in displayed customers" placeholder="Find customer ID" value={search} onChange={e=>setSearch(e.target.value)}/></label>}>
        {!visible.length?<Empty>No customers match. Try broader filters or clear your search.</Empty>:<div className="table-scroll customer-table unified-worklist"><table><thead><tr>{['Customer','Value (RM)','Value band','Risk','Recommended next action','Candidate offer','Renewal','Preferred channel'].map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{visible.map(r=><tr key={r.CUSTOMER_ID} className={r.CUSTOMER_ID===row?.CUSTOMER_ID?'selected':''} onClick={()=>setSelected(r.CUSTOMER_ID)}><td><button className="customer-select" onClick={()=>setSelected(r.CUSTOMER_ID)} aria-pressed={r.CUSTOMER_ID===row?.CUSTOMER_ID}>{r.CUSTOMER_ID}<ChevronRight size={13}/></button></td><td>{money(r.LIFETIME_VALUE,true)}</td><td><span className="value-band">{r.LIFETIME_VALUE_BAND}</span></td><td><Badge value={r.RETENTION_RISK_BAND}/></td><td className="action-cell">{r.ACTION}</td><td>{r.CANDIDATE_PRODUCT?<span className="offer-tag">{r.CANDIDATE_PRODUCT} · review</span>:<span className="muted">Not supported</span>}</td><td>{month(dateKey(r.NEXT_RENEWAL_MONTH))}</td><td>{r.PREFERRED_CHANNEL}</td></tr>)}</tbody></table></div>}
        <div className="worklist-footer"><span className="dot"/>Existing SQL ranking · {nbo?'Risk, customer value and renewal timing':'Retention action, customer value and risk score'} · No customer duplicated across worklist rows</div>
      </Panel>
      {row?<Panel title="Unified customer profile" className="spotlight" action={<UserRound size={20}/>}><div className="customer-id">{row.CUSTOMER_ID}</div><div className="profile-stats"><div><span>Customer value</span><b title={money(row.LIFETIME_VALUE,true)}>{money(row.LIFETIME_VALUE)}</b><small>{row.LIFETIME_VALUE_BAND} value band</small></div><div><span>Retention risk</span><Badge value={row.RETENTION_RISK_BAND}/><small>Source score {number(row.RETENTION_RISK_SCORE)}</small></div></div>
        <div className="profile-action"><div className="eyebrow">RECOMMENDED NEXT ACTION</div><h3>{row.ACTION}</h3><p>{profile.retention.action}</p><details><summary>Retention evidence<ChevronDown size={14}/></summary><ul>{profile.retention.facts.map((f,i)=><li key={i}>{f}</li>)}</ul></details></div>
        <div className="profile-action"><div className="eyebrow">CANDIDATE NEXT BEST OFFER</div><h3>{profile.offer?'Travel insurance':'No supported offer in this demo segment'}</h3><p>{profile.offer?profile.offer.action:'This customer does not match the validated consent-based Motor-to-Travel segment. No offer recommendation is made.'}</p>{profile.offer&&<details><summary>Cross-sell evidence<ChevronDown size={14}/></summary><ul>{profile.offer.facts.map((f,i)=><li key={i}>{f}</li>)}</ul></details>}</div>
        <dl><div><dt>Renewal month</dt><dd>{month(dateKey(row.NEXT_RENEWAL_MONTH))}</dd></div><div><dt>Preferred channel</dt><dd>{row.PREFERRED_CHANNEL}</dd></div><div><dt>Active policies</dt><dd>{number(row.ACTIVE_POLICY_COUNT)}</dd></div><div><dt>Marketing consent</dt><dd>{row.MARKETING_CONSENT}</dd></div><div><dt>Holds Motor / Travel</dt><dd>{row.HOLDS_MOTOR} / {row.HOLDS_TRAVEL}</dd></div></dl><div className="review-note"><Info size={16}/><span>Retention needs come first. Confirm the permitted contact route. Offers require human review; eligibility and propensity are not established.</span></div>
      </Panel>:<Panel title="Unified customer profile"><Empty>Select a customer to view evidence.</Empty></Panel>}
      </div>
      {row&&<UnifiedBrief key={view+row.CUSTOMER_ID+query(filters)+JSON.stringify(profile)} profile={profile} view={view} customer={row.CUSTOMER_ID} filters={filters} ai={ai}/>}
      <details className="methodology"><summary>Segment definitions & prioritization rules<ChevronDown size={16}/></summary><p>Customer Priorities and Retention Actions reuse the existing NBA order: High risk + High/Top value + upcoming renewal → Priority retention review. Other High risk → Retention review. Medium + upcoming renewal → Proactive renewal engagement. Other Medium → Monitor retention needs. Low → Standard relationship maintenance. Ties: value, risk score and customer ID.</p><p>Cross-Sell Opportunities reuses the existing NBO segment: Motor held; Travel not held; next-best-product Travel; marketing consent Yes. Ranking remains Low risk, Medium, High; lifetime value descending; upcoming renewal first; renewal month and customer ID. A high-risk candidate’s retention needs must be reviewed before a Travel discussion.</p><p>Renewal window: {renewalStart?.toLocaleDateString('en-GB')}–{renewalEnd?.toLocaleDateString('en-GB')}, the next three full months after the snapshot. Missing renewal dates never qualify as upcoming. Portfolio and opportunity categories overlap and must not be added. No new model, eligibility decision or automatic contact.</p></details>
    </>}
    </div>
  </>;
}

functions.Variance:
function Variance({rows,level,metric}){
  const key=metric+'_VARIANCE',name=level==='LINE'?'LINE_OF_BUSINESS':'DISTRIBUTION_CHANNEL';
  const group=rows.filter(r=>r.LEVEL===level),data=group.filter(r=>valid(r[key])&&r.MISSING_ACTUAL===0&&r.MISSING_PLAN===0&&r.KEY_COUNT>0).sort((a,b)=>a[key]-b[key]);
  return <Panel title={level==='LINE'?'By business line':'By distribution channel'}>{!data.length?<Empty>No fully comparable actual / plan groups.</Empty>:<div className="chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={data} layout="vertical" margin={{top:12,right:22,bottom:8,left:0}} barSize={25}><CartesianGrid stroke="#EEF0F4" horizontal={false}/><XAxis type="number" tickFormatter={v=>money(v)} axisLine={false} tickLine={false}/><YAxis type="category" dataKey={name} width={level==='LINE'?70:120} axisLine={false} tickLine={false} tick={{fontSize:11}}/><Tooltip formatter={v=>money(v,true)} labelFormatter={v=>v}/><ReferenceLine x={0} stroke="#DFE4EC"/><Bar dataKey={key} name={metric+' variance'} radius={3} isAnimationActive={false}>{data.map((r,i)=><Cell key={i} fill={r[key]<0?RED:GREEN}/>)}</Bar></BarChart></ResponsiveContainer></div>}<p className="footnote">{metric} actual − plan · Red below plan / green above plan{group.length>data.length?` · ${group.length-data.length} unavailable groups excluded`:''}</p></Panel>;
}

functions.Mix:
function Mix({rows,level,metric}){
  const data=rows.filter(r=>r.LEVEL===level).sort((a,b)=>b[metric]-a[metric]),field=level==='LINE'?'LINE_OF_BUSINESS':'DISTRIBUTION_CHANNEL',share=metric+'_SHARE';
  return <Panel title={level==='LINE'?'Business line premium mix':'Distribution channel premium mix'}>{!data.length||data.some(r=>!valid(r[share]))?<Empty>Shares unavailable for missing, negative or zero-total premium.</Empty>:<div className="mix-layout"><div className="donut"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={data} dataKey={share} nameKey={field} innerRadius="62%" outerRadius="90%" paddingAngle={2} stroke="white" isAnimationActive={false}>{data.map((r,i)=><Cell key={i} fill={COLORS[i%COLORS.length]}/>)}</Pie><Tooltip formatter={v=>pct(v)}/></PieChart></ResponsiveContainer><div className="donut-center">{metric}<small>premium mix</small></div></div><div className="mix-legend">{data.map((r,i)=><div key={r[field]}><span className="dot" style={{background:COLORS[i%COLORS.length]}}/><span title={r[field]}>{r[field]}</span><b title={money(r[metric],true)}>{pct(r[share])}</b></div>)}</div></div>}<p className="footnote">SQL-calculated share of selected actual {metric}. Same filters and a separate denominator for each premium basis.</p></Panel>;
}

functions.ChannelTable:
function ChannelTable({rows}){
  const [sort,setSort]=useState(['GWP',-1]);
  const fields=[['DISTRIBUTION_CHANNEL','Channel'],['GWP','GWP actual'],['PLAN_GWP','GWP plan'],['GWP_VARIANCE','GWP variance'],['GWP_VARIANCE_PCT','Variance %'],['NEP','NEP'],['NET_INCURRED_CLAIMS','Net incurred'],['LOSS_RATIO','Loss ratio']];
  const data=[...rows.filter(r=>r.LEVEL==='CHANNEL')].sort((a,b)=>{const x=a[sort[0]],y=b[sort[0]];if(x===null)return 1;if(y===null)return -1;return (typeof x==='string'?x.localeCompare(y):x-y)*sort[1];});
  return <Panel title="Channel performance scorecard" subtitle="Compare distribution performance. Select a column heading to sort."><div className="table-scroll"><table><thead><tr>{fields.map(([key,label])=><th key={key} aria-sort={sort[0]===key?(sort[1]===1?'ascending':'descending'):'none'}><button onClick={()=>setSort([key,sort[0]===key?-sort[1]:1])}>{label}<ArrowUpDown size={12}/></button></th>)}</tr></thead><tbody>{data.map(r=><tr key={r.DISTRIBUTION_CHANNEL}>{fields.map(([key])=><td key={key} title={key==='DISTRIBUTION_CHANNEL'?undefined:money(r[key],true)} className={key.includes('VARIANCE')&&valid(r[key])?(r[key]<0?'negative':'positive'):''}>{key==='DISTRIBUTION_CHANNEL'?r[key]:key.includes('PCT')||key==='LOSS_RATIO'?pct(r[key]):money(r[key])}</td>)}</tr>)}</tbody></table></div></Panel>;
}
